
// Shared subtle video background on every page. Low-cost single muted loop.
(function(){
 const addVideo=()=>{
  if(document.querySelector('.nx-video-bg')) return;
  const video=document.createElement('video');
  video.className='nx-video-bg'; video.autoplay=true; video.muted=true; video.loop=true; video.playsInline=true;
  video.setAttribute('aria-hidden','true'); video.preload='metadata';
  video.src=location.pathname.includes('/pages/')?'../assets/nexora-bg.mp4':'assets/nexora-bg.mp4';
  document.body.prepend(video);
  const play=video.play(); if(play&&play.catch) play.catch(()=>{});
 };
 if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',addVideo,{once:true}); else addVideo();
})();

