function getCart(){try{return JSON.parse(localStorage.getItem('nexoraCart')||'[]')}catch{return []}}
function saveCart(c){localStorage.setItem('nexoraCart',JSON.stringify(c));updateCartCount()}
function updateCartCount(){const n=getCart().reduce((s,x)=>s+x.qty,0);$$('.cart-count').forEach(e=>e.textContent=n)}
function addToCart(id){const p=products.find(x=>x.id===id);if(!p)return;let c=getCart(),item=c.find(x=>x.id===id);if(item)item.qty++;else c.push({id,qty:1});saveCart(c);toast(p.name+' added to cart')}
function money(n){return '$'+Number(n).toFixed(2)}
function catalogCard(p){return `<article class="catalog-card edge-glow"><a href="service-details.html?service=${p.id}"><div class="catalog-art"><img src="${p.image}" alt="${p.name} service preview" loading="lazy"><small>${p.tag}</small></div></a><div class="catalog-body"><div class="card-kicker">${p.category.toUpperCase()}</div><h3>${p.name}</h3><p>${p.desc}</p><div class="catalog-meta"><span>◷ ${p.days} days</span><strong>${money(p.price)}</strong></div><div class="catalog-actions"><button class="btn" data-add="${p.id}">＋ Add to cart</button><a class="btn btn-outline" href="service-details.html?service=${p.id}">Details</a></div></div></article>`}
function initServices(){const grid=$('#catalog-grid');if(!grid)return;let category='All';const search=$('#service-search'),sort=$('#service-sort');function render(){let list=products.filter(p=>(category==='All'||p.category===category)&&(`${p.name} ${p.desc} ${p.category}`).toLowerCase().includes(search.value.toLowerCase()));if(sort.value==='price-low')list.sort((a,b)=>a.price-b.price);if(sort.value==='price-high')list.sort((a,b)=>b.price-a.price);if(sort.value==='name')list.sort((a,b)=>a.name.localeCompare(b.name));grid.innerHTML=list.map(catalogCard).join('')||'<div class="content-panel">No services match your search.</div>';$('#result-count').textContent=list.length+' services available';}$$('[data-category]').forEach(b=>b.addEventListener('click',()=>{$$('[data-category]').forEach(x=>x.classList.remove('active'));b.classList.add('active');category=b.dataset.category;render()}));search.addEventListener('input',render);sort.addEventListener('change',render);grid.addEventListener('click',e=>{const b=e.target.closest('[data-add]');if(b)addToCart(b.dataset.add)});render()}
function initDetail(){const el=$('#service-detail');if(!el)return;const id=new URLSearchParams(location.search).get('service')||'web',p=products.find(x=>x.id===id)||products[0];el.innerHTML=`<div><div class="detail-art"><img src="${p.image}" alt="${p.name} service preview" loading="eager" onerror="this.style.display='none';this.parentElement.classList.add('detail-art-fallback');this.parentElement.textContent='${p.symbol.replace("'", "\'")}'"></div><div class="content-panel" style="margin-top:18px"><div class="eyebrow">WHAT'S INCLUDED</div><h2>Built around your goals.</h2><ul class="feature-list">${p.features.map(x=>`<li>${x}</li>`).join('')}</ul></div></div><aside class="content-panel"><div class="eyebrow">${p.category.toUpperCase()} SERVICE</div><h1 style="font:800 30px Manrope;letter-spacing:-.04em">${p.name}</h1><p style="color:var(--muted);font-size:12px;line-height:1.8">${p.desc}</p><div class="detail-price">${money(p.price)}</div><p class="form-note">Estimated delivery: ${p.days} days · Sample price</p><button class="btn" style="width:100%;margin:18px 0" data-add="${p.id}">Add to cart ↗</button><div class="notice">Demo catalogue: connect the admin panel and Firebase before accepting real orders.</div><p class="form-note">Need a custom scope? Send a request from your dashboard after account features are connected.</p></aside>`;el.addEventListener('click',e=>{const b=e.target.closest('[data-add]');if(b)addToCart(b.dataset.add)})}
function initCart(){
 const el=$('#cart-content');if(!el)return;
 function render(){
  const c=getCart(),items=c.map(x=>({...x,p:products.find(p=>p.id===x.id)})).filter(x=>x.p);
  if(!items.length){el.innerHTML='<div class="empty-state"><div class="empty-icon">♧</div><h2>Your cart is empty</h2><p>Looks like you haven’t added anything yet.<br>Browse services to find what you need.</p><a class="btn" href="services.html">Browse services →</a></div>';return;}
  const total=items.reduce((sum,x)=>sum+x.p.price*x.qty,0);
  el.innerHTML=`<div class="two-col"><div class="content-panel"><h2>Your selections</h2>${items.map(x=>`<div class="cart-line"><div><strong>${x.p.name}</strong><p class="form-note">${money(x.p.price)} each</p></div><div class="cart-qty"><button type="button" data-minus="${x.id}">−</button><span>${x.qty}</span><button type="button" data-plus="${x.id}">+</button><button type="button" class="remove" data-remove="${x.id}">Remove</button></div></div>`).join('')}</div><aside class="content-panel"><div class="eyebrow">ORDER SUMMARY</div><h2>${money(total)}</h2><p class="form-note">Total · USD</p><div id="checkout-error" class="checkout-error" role="alert" aria-live="assertive" hidden></div><button type="button" class="btn" id="checkout" style="width:100%;margin:15px 0">Continue to checkout ↗</button><div class="notice">Your wallet balance will be checked before an order is accepted. Orders are charged in USD.</div></aside></div>`;
 }
 el.addEventListener('click',e=>{
  const b=e.target.closest('button');if(!b)return;
  let c=getCart();
  if(b.dataset.plus){const x=c.find(x=>x.id===b.dataset.plus);if(x)x.qty++;saveCart(c);render();return;}
  if(b.dataset.minus){const x=c.find(x=>x.id===b.dataset.minus);if(x)x.qty=Math.max(1,x.qty-1);saveCart(c);render();return;}
  if(b.dataset.remove){c=c.filter(x=>x.id!==b.dataset.remove);saveCart(c);render();return;}
  if(b.id!=='checkout')return;
  (async()=>{
   const errBox=$('#checkout-error',el);const showError=(message)=>{if(errBox){errBox.textContent=message;errBox.hidden=false;}toast(message);};
   b.disabled=true;b.textContent='Checking wallet…';if(errBox){errBox.hidden=true;errBox.textContent='';}
   try{
    const rt=await firebaseTools();
    if(!rt.user){location.href='sign-in.html?required=1';return;}
    if(!rt.user.emailVerified){showError('Please verify your email before placing an order.');return;}
    const current=getCart().map(x=>({...x,p:products.find(p=>p.id===x.id)})).filter(x=>x.p&&Number.isInteger(Number(x.qty))&&Number(x.qty)>0);
    if(!current.length){showError('Your cart is empty. Please add a service first.');return;}
    const total=current.reduce((sum,x)=>sum+x.p.price*Number(x.qty),0);
    const items=current.map(x=>({serviceId:x.p.id,serviceName:x.p.name,unitPrice:x.p.price,quantity:Number(x.qty),lineTotal:x.p.price*Number(x.qty)}));
    const userRef=rt.fs.doc(rt.db,'users',rt.user.uid);
    const orderRef=rt.fs.doc(rt.fs.collection(rt.db,'orders'));
    await rt.fs.runTransaction(rt.db,async(tx)=>{
      const userSnap=await tx.get(userRef);
      if(!userSnap.exists())throw new Error('Your wallet profile was not found. Please sign out and sign in again.');
      const data=userSnap.data();
      const balance=Number(data.walletBalance);
      if(!Number.isFinite(balance)||balance<0)throw new Error('Your wallet balance is unavailable. Please contact support.');
      if(balance<total)throw new Error(`You do not have sufficient balance to complete this transaction. Order total: ${money(total)}; available balance: ${money(balance)}.`);
      const newBalance=Math.round((balance-total)*100)/100;
      tx.update(userRef,{walletBalance:newBalance,lastWalletOrderId:orderRef.id,updatedAt:rt.fs.serverTimestamp()});
      tx.set(orderRef,{userId:rt.user.uid,email:rt.user.email||'',displayName:rt.user.displayName||'',serviceId:items.length===1?items[0].serviceId:'cart',serviceName:items.length===1?items[0].serviceName:`${items.length} services`,items,amount:total,currency:'USD',quantity:items.reduce((sum,x)=>sum+x.quantity,0),status:'pending',paymentStatus:'paid-from-wallet',createdAt:rt.fs.serverTimestamp(),updatedAt:rt.fs.serverTimestamp()});
    });
    saveCart([]);toast('Order submitted successfully. Wallet balance updated.');setTimeout(()=>location.href='dashboard.html?tab=orders',650);
   }catch(err){
    console.error('Checkout failed:',err);
    let message='Could not complete checkout. Please try again.';
    if(err.message&&/sufficient balance|wallet balance|wallet profile|verify your email/i.test(err.message))message=err.message;
    else if(err.code==='permission-denied')message='Checkout was blocked by Firestore security rules. Publish the matching firestore.rules file, then try again.';
    else if(err.code==='failed-precondition')message='Wallet transaction could not be completed. Please check your Firestore setup and try again.';
    showError(message);
   }finally{if(document.body.contains(b)){b.disabled=false;b.textContent='Continue to checkout ↗';}}
  })();
 });
 render();
}
function initAuth(){const pw=$("#password"),toggle=$("#toggle-password");if(pw&&toggle)toggle.addEventListener("click",()=>pw.type=pw.type==="password"?"text":"password")}
const ADMIN_EMAIL = 'alirazaxbangash@gmail.com';
function safeText(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function dateLabel(value){try{const d=value?.toDate?value.toDate():new Date(value);return Number.isNaN(d.getTime())?'—':d.toLocaleString()}catch{return '—'}}
async function firebaseTools(){
 const [{auth,db},authSdk,fs]=await Promise.all([
  import('./firebase.js'),
  import('https://www.gstatic.com/firebasejs/11.10.0/firebase-auth.js'),
  import('https://www.gstatic.com/firebasejs/11.10.0/firebase-firestore.js')
 ]);
 const user=await new Promise(resolve=>{const stop=authSdk.onAuthStateChanged(auth,u=>{stop();resolve(u)})});
 return {auth,db,user,authSdk,fs};
}
function statusPill(status){const s=String(status||'pending');const cls=['approved','paid','completed','replied','in progress'].includes(s.toLowerCase())?'live':s.toLowerCase()==='rejected'?'rejected':'pending';return `<span class="admin-pill ${cls}">${safeText(s)}</span>`}
function initDashboard(){
 const area=$('#dashboard-area');if(!area)return;
 const tabs=[['overview','▦','Dashboard'],['orders','▣','My Orders'],['activity','◷','Activity'],['messages','✉','Messages'],['payments','＄','Payment History'],['wallet','＄','Wallet'],['settings','⚙','Settings']];
 let section=new URLSearchParams(location.search).get('tab')||'overview';if(!tabs.some(t=>t[0]===section))section='overview';
 let runtime=null;
 const shell=(content)=>`<div class="dashboard-layout"><aside class="side-nav">${tabs.map(([k,i,l])=>`<a class="${section===k?'active':''}" href="dashboard.html?tab=${k}"><span>${i}</span>${l}</a>`).join('')}</aside><section class="dashboard-main">${content}</section></div>`;
 const empty=(icon,title,desc)=>`<div class="empty-state"><div class="empty-icon">${icon}</div><h2>${title}</h2><p>${desc}</p></div>`;
 async function loadRows(collectionName){const {db,user,fs}=runtime;const snap=await fs.getDocs(fs.query(fs.collection(db,collectionName),fs.where('userId','==',user.uid)));return snap.docs.map(d=>({id:d.id,...d.data()})).sort((a,b)=>new Date(b.createdAt?.toDate?.()||b.createdAt||0)-new Date(a.createdAt?.toDate?.()||a.createdAt||0));}
 async function render(){
  if(!runtime){area.innerHTML=shell(`<div class="content-panel"><h2>Loading your workspace…</h2><p class="form-note">Connecting to your account.</p></div>`);return;}
  const {user,db,fs}=runtime;let orders=[],messages=[],deposits=[],walletBalance=0,loadError='';
  try{[orders,messages,deposits]=await Promise.all([loadRows('orders'),loadRows('messages'),loadRows('deposits')]);const walletSnap=await fs.getDoc(fs.doc(db,'users',user.uid));walletBalance=walletSnap.exists()?Math.max(0,Number(walletSnap.data().walletBalance)||0):0}catch(e){loadError='Your Firebase data could not be loaded yet. Check that the secure Firestore Rules from firestore.rules have been published.';console.warn('Dashboard Firestore load:',e)}
  let content='';
  if(section==='overview')content=`<div class="admin-welcome"><div><div class="eyebrow">YOUR WORKSPACE</div><h2>Welcome${user.displayName?`, <em>${safeText(user.displayName)}</em>`:''}.</h2><p>Orders, messages and payment requests in one place.</p></div><a class="btn" href="services.html">Explore services ↗</a></div><div class="stats-grid"><div class="stat-card wallet-stat-card"><span>USD WALLET BALANCE</span><strong>${money(walletBalance)}</strong><small>Available balance · <a href="dashboard.html?tab=wallet">Manage wallet ↗</a></small></div><div class="stat-card"><span>My orders</span><strong>${orders.length}</strong></div><div class="stat-card"><span>Messages</span><strong>${messages.length}</strong></div><div class="stat-card"><span>Payment requests</span><strong>${deposits.length}</strong></div></div>${loadError?`<div class="notice">${loadError}</div>`:''}<div class="content-panel"><div class="section-heading"><h3>Recent activity</h3><a class="text-link" href="dashboard.html?tab=activity">View activity →</a></div>${orders.length||messages.length||deposits.length?`<div class="admin-message-list">${[...orders.map(x=>({kind:'Order',title:x.serviceName||x.service||'Service order',status:x.status,date:x.createdAt})),...messages.map(x=>({kind:'Message',title:x.subject,status:x.status,date:x.createdAt})),...deposits.map(x=>({kind:'Payment',title:`${x.method||'Manual'} · ${x.amount}`,status:x.status,date:x.createdAt}))].sort((a,b)=>new Date(b.date?.toDate?.()||b.date||0)-new Date(a.date?.toDate?.()||a.date||0)).slice(0,6).map(x=>`<article><span class="admin-user-avatar">${x.kind==='Order'?'▣':x.kind==='Message'?'✉':'＄'}</span><div><b>${safeText(x.title)}</b><p>${x.kind} · ${safeText(x.status||'pending')}</p><small>${dateLabel(x.date)}</small></div>${statusPill(x.status)}</article>`).join('')}</div>`:empty('✦','Your workspace is ready','Your real orders, messages and payment requests will appear here after you submit them.')}</div>`;
  else if(section==='orders')content=`<h2>My Orders</h2><p>Track service requests and project progress.</p>${loadError?`<div class="notice">${loadError}</div>`:''}<div class="content-panel">${orders.length?`<div class="admin-table-wrap"><table class="data-table admin-table"><thead><tr><th>ORDER</th><th>SERVICE</th><th>AMOUNT</th><th>STATUS</th><th>CREATED</th></tr></thead><tbody>${orders.map(o=>`<tr><td><b>${safeText(o.id.slice(0,8).toUpperCase())}</b></td><td>${safeText(o.serviceName||o.service||'Service')}</td><td>${safeText(o.currency||'USD')} ${safeText(o.amount??'—')}</td><td>${statusPill(o.status)}</td><td>${dateLabel(o.createdAt)}</td></tr>`).join('')}</tbody></table></div>`:empty('▣','No orders yet','Choose a service and contact Nexora to start your first project.')}</div>`;
  else if(section==='activity')content=`<h2>Activity</h2><p>A timeline of your orders, conversations and payment requests.</p><div class="content-panel">${orders.length+messages.length+deposits.length?`<div class="admin-message-list">${[...orders.map(x=>({kind:'Order',title:x.serviceName||x.service||'Service order',status:x.status,date:x.createdAt})),...messages.map(x=>({kind:'Message',title:x.subject,status:x.status,date:x.createdAt})),...deposits.map(x=>({kind:'Payment request',title:`${x.method||'Manual'} · ${x.amount}`,status:x.status,date:x.createdAt}))].sort((a,b)=>new Date(b.date?.toDate?.()||b.date||0)-new Date(a.date?.toDate?.()||a.date||0)).map(x=>`<article><span class="admin-user-avatar">•</span><div><b>${safeText(x.title)}</b><p>${safeText(x.kind)} · ${safeText(x.status||'pending')}</p><small>${dateLabel(x.date)}</small></div>${statusPill(x.status)}</article>`).join('')}</div>`:empty('◷','No activity yet','Your activity will appear here when you submit an order, message or payment request.')}</div>`;
  else if(section==='messages')content=`<h2>Messages</h2><p>Send a message to Nexora and see replies from the admin in this page.</p>${loadError?`<div class="notice">${loadError}</div>`:''}<div class="content-panel"><form id="message-form"><div class="form-field"><label for="message-subject">Subject</label><input id="message-subject" name="subject" required maxlength="120" placeholder="What do you need help with?"></div><div class="form-field"><label for="message-body">Message</label><textarea id="message-body" name="message" required maxlength="4000" placeholder="Write your message…"></textarea></div><button class="btn" type="submit">Send message ↗</button><p class="form-note" id="message-feedback">Messages are stored in your account and visible to the authorized admin.</p></form></div><div class="content-panel" style="margin-top:16px"><h3>Conversation history</h3>${messages.length?`<div class="admin-message-list">${messages.map(m=>`<article><span class="admin-user-avatar">✉</span><div><b>${safeText(m.subject)}</b><p>${safeText(m.message)}</p>${m.adminReply?`<div class="notice"><b>Admin reply</b><br>${safeText(m.adminReply)}</div>`:''}<small>${dateLabel(m.createdAt)}</small></div>${statusPill(m.status)}</article>`).join('')}</div>`:empty('✉','No messages yet','Your messages and admin replies will appear here.')}</div>`;
  else if(section==='payments')content=`<h2>Payment History</h2><p>Track manual payment requests and their review status.</p><div class="notice">A request marked approved means the admin reviewed it. It does not automatically mean an online gateway charged you.</div><div class="content-panel">${deposits.length?`<div class="admin-table-wrap"><table class="data-table admin-table"><thead><tr><th>REQUEST</th><th>METHOD</th><th>AMOUNT</th><th>REFERENCE</th><th>STATUS</th><th>DATE</th></tr></thead><tbody>${deposits.map(d=>`<tr><td>${safeText(d.id.slice(0,8).toUpperCase())}</td><td>${safeText(d.method||'Manual')}</td><td>${safeText(d.currency||'USD')} ${safeText(d.amount)}</td><td>${safeText(d.transactionRef||'—')}</td><td>${statusPill(d.status)}</td><td>${dateLabel(d.createdAt)}</td></tr>`).join('')}</tbody></table></div>`:empty('＄','No payment history','Your payment requests and their status will appear here.')}</div>`;
  else if(section==='wallet')content=`<h2>Wallet</h2><p>Your USD wallet balance and payment requests. Never enter passwords, PINs or one-time codes.</p><div class="content-panel wallet-balance-panel"><div class="eyebrow">USD WALLET BALANCE</div><h3>${money(walletBalance)}</h3><p class="form-note">Your spendable balance updates when the admin approves a verified deposit.</p></div><div class="notice crypto-notice"><b>International crypto payments:</b> choose Binance Pay, Solana (SOL), or Bitcoin (BTC), then submit your transaction reference. Confirm the official receiving account/address with the site administrator before sending funds. Network fees and wrong-network transfers may be irreversible.</div><div class="content-panel"><form id="deposit-form"><div class="form-field"><label for="pay-method">Payment method</label><select id="pay-method" name="method"><option value="Binance Pay">Binance Pay</option><option value="Solana (SOL)">Solana (SOL)</option><option value="Bitcoin (BTC)">Bitcoin (BTC)</option></select></div><div class="form-field"><label for="pay-amount">Amount (USD)</label><input id="pay-amount" name="amount" type="number" min="1" max="100000" step="0.01" required placeholder="e.g. 25.00"></div><div class="form-field"><label for="pay-ref">Transaction reference</label><input id="pay-ref" name="transactionRef" required maxlength="160" placeholder="Transaction ID/reference"></div><div class="form-field"><label for="pay-notes">Notes (optional)</label><textarea id="pay-notes" name="notes" maxlength="1000" placeholder="Transfer date or additional details"></textarea></div><button class="btn" type="submit">Submit payment request ↗</button><p class="form-note" id="deposit-feedback">Your request will be marked Pending until the admin checks the transfer.</p></form><hr style="border-color:var(--line);margin:28px 0"><h3>International payment status</h3><p class="form-note">This form records a deposit request for admin review; it does not itself send crypto or connect to Binance. Only send funds after the admin provides and confirms the official payment details.</p></div>`;
  else content=`<h2>Profile Settings</h2><p>Update the name shown on your Nexora account, or request an email address change.</p><div class="content-panel"><form id="profile-settings-form"><div class="form-field"><label for="profile-display-name">Full name</label><input id="profile-display-name" name="displayName" type="text" autocomplete="name" maxlength="100" required value="${safeText(user.displayName||'')}"></div><div class="form-field"><label for="profile-email">Email address</label><input id="profile-email" name="email" type="email" autocomplete="email" maxlength="254" required value="${safeText(user.email||'')}"><small class="form-note">Changing your email requires confirmation through the new email inbox. If you change the admin account email, the Admin Panel will remain limited to the configured owner email.</small></div><div class="admin-setting-row"><div><b>Email verification</b><p>${user.emailVerified?'Verified':'Not verified'}</p></div>${statusPill(user.emailVerified?'Verified':'Pending')}</div><button class="btn" type="submit" id="profile-save-button">Save profile changes ↗</button><p class="form-note" id="profile-settings-feedback" role="status" aria-live="polite"></p></form><hr style="border-color:var(--line);margin:26px 0"><button class="btn btn-outline" id="settings-signout" type="button">Sign out</button></div>`;
  area.innerHTML=shell(content);
  $('#message-form',area)?.addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,feedback=$('#message-feedback',f),button=f.querySelector('button');button.disabled=true;try{const subject=f.elements.namedItem('subject').value.trim(),message=f.elements.namedItem('message').value.trim();if(!subject||!message)throw new Error('Please fill in both fields.');await runtime.fs.addDoc(runtime.fs.collection(runtime.db,'messages'),{userId:user.uid,email:user.email||'',displayName:user.displayName||'',subject,message,status:'open',adminReply:'',createdAt:runtime.fs.serverTimestamp(),updatedAt:runtime.fs.serverTimestamp()});toast('Message sent to Nexora admin.');f.reset();feedback.textContent='Message sent. You can check this page for an admin reply.';await render()}catch(err){feedback.textContent=err.code==='permission-denied'?'Firestore permission denied. Publish the secure rules in firestore.rules first.':(err.message||'Could not send message.');feedback.style.color='#ff9a9a'}finally{button.disabled=false}});
  $('#deposit-form',area)?.addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,feedback=$('#deposit-feedback',f),button=f.querySelector('button');button.disabled=true;try{const amount=Number(f.elements.namedItem('amount').value);if(!Number.isFinite(amount)||amount<=0)throw new Error('Enter a valid amount.');await runtime.fs.addDoc(runtime.fs.collection(runtime.db,'deposits'),{userId:user.uid,email:user.email||'',displayName:user.displayName||'',amount, currency:'USD',method:f.elements.namedItem('method').value,transactionRef:f.elements.namedItem('transactionRef').value.trim(),notes:f.elements.namedItem('notes').value.trim(),status:'pending',adminNote:'',createdAt:runtime.fs.serverTimestamp(),updatedAt:runtime.fs.serverTimestamp()});toast('Payment request submitted for review.');f.reset();feedback.textContent='Submitted. Your request is pending admin verification.';await render()}catch(err){feedback.textContent=err.code==='permission-denied'?'Firestore permission denied. Publish the secure rules in firestore.rules first.':(err.message||'Could not submit request.');feedback.style.color='#ff9a9a'}finally{button.disabled=false}});
  $('#online-payment-info',area)?.addEventListener('click',()=>toast('Online gateway is not live until merchant and server verification are configured.'));
  $('#profile-settings-form',area)?.addEventListener('submit',async e=>{
   e.preventDefault();
   const form=e.currentTarget,button=$('#profile-save-button',form),feedback=$('#profile-settings-feedback',form);
   const newName=form.elements.namedItem('displayName').value.trim();
   const newEmail=form.elements.namedItem('email').value.trim();
   if(!newName){feedback.textContent='Please enter your name.';feedback.style.color='#ff9a9a';return;}
   if(!newEmail||!newEmail.includes('@')){feedback.textContent='Please enter a valid email address.';feedback.style.color='#ff9a9a';return;}
   button.disabled=true;const original=button.textContent;button.textContent='Saving…';feedback.textContent='';feedback.style.color='';
   try{
    const nameChanged=newName!==(user.displayName||'');
    const emailChanged=newEmail.toLowerCase()!==(user.email||'').toLowerCase();
    if(nameChanged){
     await runtime.authSdk.updateProfile(user,{displayName:newName});
     await runtime.fs.setDoc(runtime.fs.doc(runtime.db,'users',user.uid),{uid:user.uid,email:user.email||'',displayName:newName,updatedAt:runtime.fs.serverTimestamp()},{merge:true});
    }
    if(emailChanged){
     if(typeof runtime.authSdk.verifyBeforeUpdateEmail!=='function'){
      throw new Error('Secure email-change confirmation is unavailable in the current Firebase SDK. Please keep your current email and contact the site administrator.');
     }
     await runtime.authSdk.verifyBeforeUpdateEmail(user,newEmail);
     feedback.textContent=nameChanged?'Name saved. A confirmation link has been sent to the new email address. Your email changes after you confirm it.':'A confirmation link has been sent to the new email address. Your email changes after you confirm it.';
    }else if(nameChanged){
     feedback.textContent='Profile name updated successfully.';
    }else{
     feedback.textContent='No changes to save.';
    }
    feedback.style.color='#a8f0c6';
    if(nameChanged){
     const heading=$('.page-hero h1');if(heading)heading.innerHTML=`Welcome,<br><em>${safeText(newName)}.</em>`;
    }
    if(!emailChanged)toast(nameChanged?'Profile updated.':'No changes to save.');
   }catch(err){
    console.error('Profile settings update failed:',err);
    const messages={
     'auth/requires-recent-login':'For security, sign out and sign in again before changing account details.',
     'auth/email-already-in-use':'That email address is already linked to another account.',
     'auth/invalid-email':'Please enter a valid email address.',
     'auth/operation-not-allowed':'Email changes are not enabled for this Firebase setup.',
     'auth/too-many-requests':'Too many attempts. Please wait and try again.'
    };
    feedback.textContent=messages[err.code]||err.message||'Could not save your profile. Please try again.';feedback.style.color='#ff9a9a';
   }finally{button.disabled=false;button.textContent=original;}
  });
 }
 area.addEventListener('click',e=>{const a=e.target.closest('[data-dashboard-tab]');if(a){section=a.dataset.dashboardTab;render()}});
 area.innerHTML=shell(`<div class="content-panel"><h2>Loading your workspace…</h2></div>`);
 firebaseTools().then(async rt=>{runtime=rt;if(!rt.user){area.innerHTML=shell(`<div class="content-panel"><h2>Sign in required</h2><p>Sign in to view your account dashboard.</p><a class="btn" href="sign-in.html">Sign in</a></div>`);return}if(!rt.user.emailVerified){area.innerHTML=shell(`<div class="notice">Please verify your email address before using your dashboard.</div>`);return}await render()}).catch(err=>{console.error(err);area.innerHTML=shell(`<div class="content-panel"><h2>Dashboard could not load</h2><p>Check your internet connection and Firebase configuration, then refresh this page.</p></div>`)});
}
function initAdmin(){
 const el=$('#admin-content');if(!el)return;
 const nav=[['overview','▦','Overview'],['services','✦','Services'],['orders','▤','Orders'],['users','♙','Users'],['deposits','＄','Payments'],['messages','✉','Messages'],['settings','⚙','Settings']];
 let section=new URLSearchParams(location.search).get('tab')||'overview';if(!nav.some(n=>n[0]===section))section='overview';let rt=null;
 const notice='Firestore is not ready or the current rules blocked this request. Publish the secure rules from firestore.rules and refresh.';
 const pill=s=>statusPill(s);
 async function rows(name){const snap=await rt.fs.getDocs(rt.fs.collection(rt.db,name));return snap.docs.map(d=>({id:d.id,...d.data()})).sort((a,b)=>new Date(b.createdAt?.toDate?.()||b.createdAt||0)-new Date(a.createdAt?.toDate?.()||a.createdAt||0));}
 function table(headers,body){return `<div class="admin-table-wrap"><table class="data-table admin-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${body||`<tr><td colspan="${headers.length}">No records yet.</td></tr>`}</tbody></table></div>`}
 function shell(content){return `<div class="admin-app"><aside class="admin-sidebar"><a class="admin-side-brand" href="../index.html"><span class="brand-mark">N<span>✦</span></span><span>Nexora <small>ADMIN CONSOLE</small></span></a><div class="admin-side-label">WORKSPACE</div><nav class="admin-side-nav">${nav.map(([k,i,l])=>`<button type="button" class="${section===k?'active':''}" data-admin-tab="${k}"><span>${i}</span>${l}</button>`).join('')}</nav><div class="admin-sidebar-bottom"><div class="admin-profile"><span class="admin-user-avatar">A</span><div><b>${safeText(rt?.user?.displayName||'Nexora Admin')}</b><small>${safeText(rt?.user?.email||ADMIN_EMAIL)}</small></div></div><a href="../index.html">↖ <span>Back to website</span></a></div></aside><div class="admin-workspace"><header class="admin-topbar"><div><span class="admin-mobile-label">NEXORA / ADMIN</span><b>${nav.find(n=>n[0]===section)?.[2]||'Overview'}</b></div><div class="admin-top-actions"><span class="admin-live-dot">● <span>Connected workspace</span></span><a class="admin-view-site" href="../index.html">View website ↗</a><span class="admin-top-avatar">${safeText((rt?.user?.displayName||rt?.user?.email||'A').charAt(0).toUpperCase())}</span></div></header><main class="admin-main">${content}<footer class="admin-footer">© 2026 Nexora Agency <span>ADMIN CONSOLE</span></footer></main></div></div>`}
 async function render(){
  let content='';try{
   if(section==='overview'){
    const [orders,messages,deposits,services]=await Promise.all([rows('orders'),rows('messages'),rows('deposits'),rows('services')]);
    content=`<div class="admin-welcome"><div><div class="eyebrow">WORKSPACE OVERVIEW</div><h2>Good to see you, <em>Admin.</em></h2><p>Manage services, orders, client conversations and payment requests.</p></div><span class="admin-date">${new Date().toLocaleDateString()}</span></div><div class="admin-stats"><article class="admin-stat"><span class="admin-stat-icon">♙</span><span class="admin-stat-label">Client orders</span><strong>${orders.length}</strong></article><article class="admin-stat"><span class="admin-stat-icon">✉</span><span class="admin-stat-label">Messages</span><strong>${messages.filter(x=>!x.adminReply).length}</strong></article><article class="admin-stat"><span class="admin-stat-icon">＄</span><span class="admin-stat-label">Payment requests</span><strong>${deposits.filter(x=>x.status==='pending').length}</strong></article><article class="admin-stat"><span class="admin-stat-icon">✦</span><span class="admin-stat-label">Custom services</span><strong>${services.length}</strong></article><article class="admin-stat admin-wallet-stat"><span class="admin-stat-icon">＄</span><span class="admin-stat-label">WALLET & DEPOSIT REVIEW</span><strong>${deposits.filter(x=>x.status==='pending').length}</strong><small>Pending deposits · review below</small></article></div><div class="admin-overview-grid"><section class="admin-panel"><div class="admin-panel-head"><div><h3>Recent orders</h3><p>Live Firestore records</p></div><button class="chip" data-admin-tab="orders">View all</button></div>${table(['ORDER','CLIENT','SERVICE','STATUS'],orders.slice(0,5).map(o=>`<tr><td><b>${safeText(o.id.slice(0,8).toUpperCase())}</b></td><td>${safeText(o.email||'—')}</td><td>${safeText(o.serviceName||o.service||'Service')}</td><td>${pill(o.status)}</td></tr>`).join(''))}</section><section class="admin-panel"><div class="admin-panel-head"><div><h3>Quick actions</h3><p>Go to a workspace section</p></div></div><div class="admin-quick-actions"><button data-admin-tab="messages"><span>✉</span><div><b>Reply to messages</b><small>${messages.filter(x=>!x.adminReply).length} waiting for reply</small></div><i>↗</i></button><button data-admin-tab="deposits"><span>＄</span><div><b>Review payments</b><small>${deposits.filter(x=>x.status==='pending').length} pending requests</small></div><i>↗</i></button><button data-admin-tab="services"><span>✦</span><div><b>Manage services</b><small>Add or update your catalogue</small></div><i>↗</i></button></div></section></div>`;
   }else if(section==='services'){
    const services=await rows('services');content=`<div class="admin-welcome"><div><div class="eyebrow">CATALOGUE</div><h2>Manage <em>services.</em></h2><p>Import the built-in catalogue once to manage its prices here. Saved active service records are loaded into the public catalogue from Firestore.</p></div></div><section class="admin-panel"><div class="admin-panel-head"><div><h3>Add a service</h3><p>Import the current built-in catalogue once to manage its prices here too.</p></div><button type="button" class="btn btn-outline btn-small" id="admin-sync-services">Import built-in services</button></div><form id="admin-service-form" class="two-col"><div class="form-field"><label>Name</label><input name="name" required maxlength="100" placeholder="Website Development"></div><div class="form-field"><label>Category</label><input name="category" required maxlength="60" placeholder="Development"></div><div class="form-field"><label>Price (USD)</label><input name="price" type="number" min="0" step="0.01" required></div><div class="form-field"><label>Delivery days</label><input name="days" type="number" min="1" max="365" required value="7"></div><div class="form-field" style="grid-column:1/-1"><label>Description</label><textarea name="description" required maxlength="1000"></textarea></div><button class="btn" type="submit">Add service ↗</button></form></section><section class="admin-panel" style="margin-top:14px"><div class="admin-panel-head"><div><h3>Saved services</h3><p>Manage custom service records</p></div></div>${table(['SERVICE','CATEGORY','PRICE','DAYS','STATUS','ACTION'],services.map(s=>`<tr><td><b>${safeText(s.name)}</b></td><td>${safeText(s.category)}</td><td>$${Number(s.price||0).toFixed(2)}</td><td>${safeText(s.days||'—')}</td><td>${s.active===false?statusPill('inactive'):statusPill('active')}</td><td><button class="chip" data-edit-service="${safeText(s.id)}">Edit</button> <button class="chip" data-delete-service="${safeText(s.id)}">${s.active===false?'Restore':'Deactivate'}</button></td></tr>`).join(''))}</section>`;
   }else if(section==='orders'){
    const orders=await rows('orders');content=`<div class="admin-welcome"><div><div class="eyebrow">PROJECT PIPELINE</div><h2>Client <em>orders.</em></h2><p>Update order progress. Only orders actually submitted by users are shown.</p></div></div><section class="admin-panel">${table(['ORDER','CLIENT','SERVICE','AMOUNT','STATUS','UPDATE'],orders.map(o=>`<tr><td><b>${safeText(o.id.slice(0,8).toUpperCase())}</b></td><td>${safeText(o.email||'—')}</td><td>${safeText(o.serviceName||o.service||'Service')}</td><td>${safeText(o.currency||'USD')} ${safeText(o.amount??'—')}</td><td>${pill(o.status)}</td><td><select data-order-status="${safeText(o.id)}"><option ${o.status==='pending'?'selected':''}>pending</option><option ${o.status==='in progress'?'selected':''}>in progress</option><option ${o.status==='completed'?'selected':''}>completed</option><option ${o.status==='cancelled'?'selected':''}>cancelled</option></select></td></tr>`).join(''))}</section>`;
   }else if(section==='users'){
    const users=await rows('users');content=`<div class="admin-welcome"><div><div class="eyebrow">ACCOUNT DIRECTORY</div><h2>Manage <em>users.</em></h2><p>Only profile documents saved by the app are listed here. Firebase Authentication accounts cannot be enumerated securely from browser JavaScript.</p></div></div><section class="admin-panel">${table(['NAME','EMAIL','UID','JOINED'],users.map(u=>`<tr><td><b>${safeText(u.displayName||'—')}</b></td><td>${safeText(u.email||'—')}</td><td>${safeText(u.uid||u.id)}</td><td>${dateLabel(u.createdAt)}</td></tr>`).join(''))}</section>`;
   }else if(section==='deposits'){
    const deposits=await rows('deposits');content=`<div class="admin-welcome"><div><div class="eyebrow">PAYMENT REVIEW</div><h2>Payment <em>requests.</em></h2><p>Verify each transfer in the actual payment account before approving it.</p></div></div><div class="notice admin-wallet-notice"><b>Wallet approval:</b> verify the payment in the receiving account first. Approving a pending request credits its USD amount to the user wallet once; rejecting it does not credit funds.</div><section class="admin-panel">${table(['REQUEST','CLIENT','METHOD','AMOUNT','REFERENCE','STATUS','REVIEW'],deposits.map(d=>`<tr><td>${safeText(d.id.slice(0,8).toUpperCase())}</td><td>${safeText(d.email||'—')}</td><td>${safeText(d.method||'—')}</td><td>${safeText(d.currency||'USD')} ${safeText(d.amount)}</td><td>${safeText(d.transactionRef||'—')}</td><td>${pill(d.status)}</td><td><select data-deposit-status="${safeText(d.id)}"><option value="pending" ${d.status==='pending'?'selected':''}>Pending</option><option value="approved" ${d.status==='approved'?'selected':''}>Approve</option><option value="rejected" ${d.status==='rejected'?'selected':''}>Reject</option></select></td></tr>`).join(''))}</section>`;
   }else if(section==='messages'){
    const messages=await rows('messages');content=`<div class="admin-welcome"><div><div class="eyebrow">SUPPORT INBOX</div><h2>Client <em>messages.</em></h2><p>Reply here; the customer sees your reply in their dashboard.</p></div></div><section class="admin-panel">${messages.length?messages.map(m=>`<article class="admin-message-list" style="padding:15px 0;border-bottom:1px solid var(--line)"><div style="display:flex;gap:12px;align-items:flex-start"><span class="admin-user-avatar">✉</span><div style="flex:1;min-width:0"><b>${safeText(m.subject)}</b><p>${safeText(m.email||'Unknown client')} · ${dateLabel(m.createdAt)}</p><p>${safeText(m.message)}</p>${m.adminReply?`<div class="notice"><b>Current reply</b><br>${safeText(m.adminReply)}</div>`:''}<form data-reply-form="${safeText(m.id)}"><div class="form-field"><label>Admin reply</label><textarea name="adminReply" required maxlength="4000" placeholder="Write your reply…">${safeText(m.adminReply||'')}</textarea></div><div class="form-field"><label>Status</label><select name="status"><option value="open" ${m.status==='open'?'selected':''}>Open</option><option value="replied" ${m.status==='replied'?'selected':''}>Replied</option><option value="closed" ${m.status==='closed'?'selected':''}>Closed</option></select></div><button class="btn btn-small" type="submit">Save reply</button></form></div></div></article>`).join(''):'<p class="form-note">No messages yet. Customer messages will appear here after Firestore is connected.</p>'}</section>`;
   }else content=`<div class="admin-welcome"><div><div class="eyebrow">WORKSPACE PREFERENCES</div><h2>Admin <em>settings.</em></h2><p>Secure administrator account and integration status.</p></div></div><section class="admin-panel"><div class="admin-setting-row"><div><b>Admin account</b><p>${safeText(rt?.user?.email||'')}</p></div><span class="admin-pill live">Verified session</span></div><div class="admin-setting-row"><div><b>Database</b><p>Firestore live data access depends on firestore.rules.</p></div><span class="admin-pill pending">Check rules</span></div><div class="admin-setting-row"><div><b>Online payment gateway</b><p>Not active until merchant onboarding and a trusted server-side verification endpoint are configured.</p></div><span class="admin-pill pending">Not configured</span></div><div class="notice" style="margin-top:18px">Never place merchant secret keys in HTML or JavaScript. Firebase Spark does not provide Cloud Functions deployment; a separate trusted backend or an eligible provider integration is required.</div><button class="btn btn-outline" id="admin-signout" type="button">Sign out</button></section>`;
  }catch(err){console.error('Admin data load failed:',err);content=`<div class="admin-welcome"><div><div class="eyebrow">ADMIN CONSOLE</div><h2>Could not load <em>workspace data.</em></h2><p>${safeText(err.code==='permission-denied'?notice:(err.message||notice))}</p></div></div><div class="notice">${safeText(notice)} Your page layout is working, but Firestore access must be configured.</div>`;}
  el.innerHTML=shell(content);
  $$('[data-admin-tab]',el).forEach(b=>b.addEventListener('click',()=>{section=b.dataset.adminTab;render()}));
  $('#admin-sync-services',el)?.addEventListener('click',async()=>{const builtinIds=['web','portfolio','brand','thumb','video','social','youtube-thumb','discord-server','minecraft-profile','minecraft-logo'];const button=$('#admin-sync-services',el);button.disabled=true;try{for(const id of builtinIds){const p=products.find(x=>x.id===id);if(!p)continue;const ref=rt.fs.doc(rt.db,'services',id);const existing=await rt.fs.getDoc(ref);if(!existing.exists())await rt.fs.setDoc(ref,{name:p.name,category:p.category,price:p.price,days:p.days,tag:p.tag,symbol:p.symbol,image:p.image,description:p.desc,features:p.features,active:true,createdAt:rt.fs.serverTimestamp(),updatedAt:rt.fs.serverTimestamp()})}toast('Built-in services imported.');await render()}catch(err){toast('Could not import services; check Firestore Rules.');console.error(err)}finally{button.disabled=false}});
  $('#admin-service-form',el)?.addEventListener('submit',async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('button');b.disabled=true;try{await rt.fs.addDoc(rt.fs.collection(rt.db,'services'),{name:f.elements.namedItem('name').value.trim(),category:f.elements.namedItem('category').value.trim(),price:Number(f.elements.namedItem('price').value),days:Number(f.elements.namedItem('days').value),description:f.elements.namedItem('description').value.trim(),active:true,createdAt:rt.fs.serverTimestamp(),updatedAt:rt.fs.serverTimestamp()});toast('Service saved.');await render()}catch(err){toast(err.code==='permission-denied'?'Firestore rules blocked saving.':'Could not save service.');console.error(err)}finally{b.disabled=false}});
  $$('[data-edit-service]',el).forEach(b=>b.addEventListener('click',async()=>{try{const snap=await rt.fs.getDoc(rt.fs.doc(rt.db,'services',b.dataset.editService));if(!snap.exists())return toast('Service record not found.');const v=snap.data();const name=prompt('Service name:',v.name||'');if(name===null)return;const category=prompt('Category:',v.category||'Custom');if(category===null)return;const price=prompt('Price (USD):',String(v.price??0));if(price===null)return;const days=prompt('Delivery days:',String(v.days??7));if(days===null)return;const description=prompt('Description:',v.description||'');if(description===null)return;if(!name.trim()||!category.trim()||!Number.isFinite(Number(price))||Number(price)<0||!Number.isFinite(Number(days))||Number(days)<1)throw new Error('Please enter valid service details.');await rt.fs.updateDoc(rt.fs.doc(rt.db,'services',b.dataset.editService),{name:name.trim(),category:category.trim(),price:Number(price),days:Number(days),description:description.trim(),updatedAt:rt.fs.serverTimestamp()});toast('Service updated.');await render()}catch(err){toast(err.message||'Could not update service.');console.error(err)}}));
  $$('[data-delete-service]',el).forEach(b=>b.addEventListener('click',async()=>{const current=await rt.fs.getDoc(rt.fs.doc(rt.db,'services',b.dataset.deleteService));if(!current.exists())return;const nextActive=current.data().active===false;if(!confirm(nextActive?'Restore this service to the public catalogue?':'Deactivate this service from the public catalogue?'))return;try{await rt.fs.updateDoc(rt.fs.doc(rt.db,'services',b.dataset.deleteService),{active:nextActive,updatedAt:rt.fs.serverTimestamp()});toast(nextActive?'Service restored.':'Service deactivated.');await render()}catch(err){toast('Could not update service; check Firestore Rules.')}}));
  $$('[data-order-status]',el).forEach(s=>s.addEventListener('change',async()=>{try{await rt.fs.updateDoc(rt.fs.doc(rt.db,'orders',s.dataset.orderStatus),{status:s.value,updatedAt:rt.fs.serverTimestamp()});toast('Order status updated.')}catch(err){toast('Could not update order status.');console.error(err)}}));
  $$('[data-deposit-status]',el).forEach(s=>s.addEventListener('change',async()=>{const nextStatus=s.value;const adminNote=prompt('Optional review note (never enter passwords, PINs or recovery phrases):','');s.disabled=true;try{const depositRef=rt.fs.doc(rt.db,'deposits',s.dataset.depositStatus);await rt.fs.runTransaction(rt.db,async(tx)=>{const depSnap=await tx.get(depositRef);if(!depSnap.exists())throw new Error('Deposit request not found.');const dep=depSnap.data();if(dep.status==='approved')throw new Error('This request has already been approved.');if(nextStatus==='approved'){if(dep.status!=='pending')throw new Error('Only pending requests can be approved.');const userRef=rt.fs.doc(rt.db,'users',dep.userId);const userSnap=await tx.get(userRef);const current=Math.max(0,Number(userSnap.exists()?userSnap.data().walletBalance:0)||0);tx.set(userRef,{uid:dep.userId,email:dep.email,displayName:dep.displayName||'',walletBalance:Math.round((current+Number(dep.amount))*100)/100,updatedAt:rt.fs.serverTimestamp()},{merge:true});}tx.update(depositRef,{status:nextStatus,adminNote:adminNote||'',reviewedBy:rt.user.email,updatedAt:rt.fs.serverTimestamp()});});toast(nextStatus==='approved'?'Deposit approved and USD wallet credited.':'Payment request status updated.');await render()}catch(err){toast(err.message||'Could not update payment request; publish the updated Firestore Rules.');console.error(err);await render()}finally{s.disabled=false}}));
  $$('[data-reply-form]',el).forEach(f=>f.addEventListener('submit',async e=>{e.preventDefault();const b=f.querySelector('button');b.disabled=true;try{await rt.fs.updateDoc(rt.fs.doc(rt.db,'messages',f.dataset.replyForm),{adminReply:f.elements.namedItem('adminReply').value.trim(),status:f.elements.namedItem('status').value,updatedAt:rt.fs.serverTimestamp()});toast('Reply saved for the customer.');await render()}catch(err){toast('Could not save reply; check Firestore Rules.');console.error(err)}finally{b.disabled=false}}));
  $('#admin-signout',el)?.addEventListener('click',async()=>{await rt.authSdk.signOut(rt.auth);location.href='sign-in.html'});
 }
 el.innerHTML='<div class="content-panel"><h2>Verifying admin access…</h2><p class="form-note">Only the authorized Nexora administrator can open this workspace.</p></div>';
 firebaseTools().then(async x=>{rt=x;if(!x.user){el.innerHTML='<div class="content-panel"><h2>Sign in required</h2><a class="btn" href="sign-in.html">Sign in</a></div>';return}if(!x.user.emailVerified||x.user.email?.toLowerCase()!==ADMIN_EMAIL){el.innerHTML='<div class="content-panel"><h2>Admin access required</h2><p>This account is not the authorized Nexora administrator.</p><a class="btn" href="dashboard.html">Return to dashboard</a></div>';return}const adminDoc=await x.fs.getDoc(x.fs.doc(x.db,'admins',ADMIN_EMAIL));if(!adminDoc.exists()){el.innerHTML='<div class="notice">Admin allowlist document was not found. Create admins/alirazaxbangash@gmail.com in Firebase Console.</div>';return}await render()}).catch(err=>{console.error('Admin auth check:',err);el.innerHTML=`<div class="content-panel"><h2>Admin access could not be verified</h2><p>${safeText(err.code==='permission-denied'?'Firestore rules are blocking the admin allowlist read. Publish the secure rules in firestore.rules.':err.message||'Check the connection and refresh.')}</p></div>`});
}
function initGetHired(){const f=$('#application-form');if(f)f.addEventListener('submit',e=>{e.preventDefault();toast('Application submission needs a secure backend before it can be delivered.')})}

function renderHomeServices(){
 const homeGrid=$('.home-services');if(!homeGrid)return;
 const homeCards=products.map((p,i)=>{
  const img=(p.image||'assets/brand-identity.svg').startsWith('../assets/')?(p.image||'../assets/brand-identity.svg').replace('../',''):(p.image||'assets/brand-identity.svg');
  const number=String(i+1).padStart(2,'0');
  return `<article class="service-card edge-glow"><a class="card-link" href="pages/service-details.html?service=${encodeURIComponent(p.id)}"><div class="card-visual visual-brand"><img class="service-photo" src="${safeText(img)}" alt="${safeText(p.name)} artwork" loading="lazy"><span class="visual-tag">${number} / ${safeText(p.tag||'SERVICE')}</span></div></a><div class="card-content"><div class="card-kicker">${safeText(p.category.toUpperCase())}</div><h3>${safeText(p.name)}</h3><p>${safeText(p.desc||'Custom digital service from Nexora Agency.')}</p><div class="card-footer"><span>From <b>${money(p.price)}</b></span><button class="btn btn-small" data-add="${safeText(p.id)}">🛒 Add to cart</button></div></div></article>`;
 }).join('');
 homeGrid.innerHTML=homeCards;
}
async function loadCustomServices(){
 try{
  const [{db},{collection,getDocs}]=await Promise.all([import('./firebase.js'),import('https://www.gstatic.com/firebasejs/11.10.0/firebase-firestore.js')]);
  const snap=await getDocs(collection(db,'services'));
  snap.docs.forEach(d=>{const v=d.data();const existingIndex=products.findIndex(p=>p.id===d.id);if(v.active===false){if(existingIndex>=0)products.splice(existingIndex,1);return}const remote={id:d.id,name:String(v.name||'Custom service'),category:String(v.category||'Custom'),price:Number(v.price||0),days:Number(v.days||7),tag:String(v.tag||v.category||'CUSTOM').toUpperCase(),symbol:String(v.symbol||'NX'),image:v.image||'../assets/brand-identity.svg',desc:String(v.description||v.desc||''),features:Array.isArray(v.features)?v.features:[]};if(existingIndex>=0)products[existingIndex]={...products[existingIndex],...remote,image:v.image||products[existingIndex].image,features:remote.features.length?remote.features:products[existingIndex].features};else products.push(remote)});
  if(snap.size){initServices();initDetail();renderHomeServices()}
 }catch(error){console.info('Custom Firestore services not loaded yet:',error.code||error.message)}
}
document.addEventListener('DOMContentLoaded',()=>{
 updateCartCount();
 // Set each header profile circle to the signed-in user's first initial.
 // If no display name exists, use the first character of the email username.
 import('./firebase.js').then(async ({auth})=>{
   const {onAuthStateChanged}=await import('https://www.gstatic.com/firebasejs/11.10.0/firebase-auth.js');
   onAuthStateChanged(auth,user=>{
     const source=(user?.displayName || user?.email?.split('@')[0] || '').trim();
     $$('.avatar').forEach(avatar=>{
       avatar.textContent=user ? (source ? Array.from(source)[0].toLocaleUpperCase() : 'A') : 'N';
       avatar.setAttribute('aria-label',user ? `${source || user.email} profile` : 'Sign in to your profile');
       avatar.title=user ? (user.displayName || user.email || 'Profile') : 'Sign in';
     });
   });
 }).catch(error=>console.warn('Profile initials could not load:',error));
 // Soft dark cursor shadow: a subtle blurred shadow follows the pointer on desktop.
 if(matchMedia('(hover:hover) and (pointer:fine)').matches&&!matchMedia('(prefers-reduced-motion: reduce)').matches){
   const shadow=document.createElement('div');shadow.className='cursor-shadow';shadow.setAttribute('aria-hidden','true');document.body.append(shadow);
   let raf=0,lastX=innerWidth/2,lastY=innerHeight/3;
   document.addEventListener('pointermove',e=>{lastX=e.clientX;lastY=e.clientY;if(raf)return;raf=requestAnimationFrame(()=>{document.documentElement.style.setProperty('--pointer-x',lastX+'px');document.documentElement.style.setProperty('--pointer-y',lastY+'px');raf=0})},{passive:true});
 }
 // Track the pointer position inside interactive cards so the thin neon border follows it.
 document.addEventListener('pointermove',e=>{const card=e.target.closest('.edge-glow');if(!card)return;const r=card.getBoundingClientRect();card.style.setProperty('--edge-x',(e.clientX-r.left)+'px');card.style.setProperty('--edge-y',(e.clientY-r.top)+'px')},{passive:true});
 document.addEventListener('click',e=>{const add=e.target.closest('[data-add]');if(add&&!add.closest('#catalog-grid'))addToCart(add.dataset.add)});
 const menu=$('.menu-toggle');menu?.addEventListener('click',()=>$('.site-header').classList.toggle('menu-open'));
 // Branded Nexora loader: show on page entry and when navigating to another local page.
 const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
 function showNexoraLoader(){
   if(reducedMotion)return null;
   let loader=$('.nexora-loader');
   if(!loader){loader=document.createElement('div');loader.className='nexora-loader';loader.setAttribute('aria-label','Loading Nexora Agency');loader.setAttribute('role','status');loader.innerHTML='<div class="nexora-loader-mark" aria-hidden="true"><span>N</span></div><div class="nexora-loader-word">NEXORA<span>AGENCY</span></div><div class="nexora-loader-track"><i></i></div>';document.body.append(loader)}
   requestAnimationFrame(()=>loader.classList.add('is-active'));
   return loader;
 }
 // Show the entry loader only on a direct page open/refresh. When navigating internally,
 // the previous page already showed it, so skip it here to avoid a double appearance.
 let arrivedFromInternalNavigation=false;
 try{arrivedFromInternalNavigation=sessionStorage.getItem('nexora-loader-navigation')==='1';sessionStorage.removeItem('nexora-loader-navigation')}catch{}
 if(!arrivedFromInternalNavigation){
   const entryLoader=showNexoraLoader();
   if(entryLoader){entryLoader.classList.add('is-active');setTimeout(()=>{entryLoader.classList.remove('is-active');setTimeout(()=>entryLoader.remove(),360)},820)}
 }
 document.addEventListener('click',e=>{
   const link=e.target.closest('a[href]');
   if(!link||e.defaultPrevented||e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey||link.target==='_blank'||link.hasAttribute('download'))return;
   const href=link.getAttribute('href');
   if(!href||href.startsWith('#')||href.startsWith('mailto:')||href.startsWith('tel:')||href.startsWith('javascript:'))return;
   let target;try{target=new URL(href,location.href)}catch{return}
   if(target.origin!==location.origin||target.pathname===location.pathname&&target.search===location.search)return;
   e.preventDefault();
   try{sessionStorage.setItem('nexora-loader-navigation','1')}catch{}
   showNexoraLoader();
   setTimeout(()=>{location.href=target.href},reducedMotion?180:480);
 });
 // Re-trigger reveal animations every time elements enter the viewport, on every page.
 const revealSelector='.hero .eyebrow,.hero h1,.hero-copy,.hero-actions,.hero-stats,.hero-preview,.ticker,.section-heading,.service-card,.process-grid article,.manifesto-inner,.cta-band,.content-panel,.page-hero,.auth-card,.legal-section,.faq-item,.stat-card,.dashboard-layout,.catalog-card,.catalog-grid,.detail-layout,.footer-main,.footer-bottom,.two-col > *, .stats-grid > *, .service-grid > *, main > section, .section-block > .section-wrap';
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 if(!reduced&&'IntersectionObserver' in window){
   const io=new IntersectionObserver(entries=>entries.forEach(entry=>{
     if(entry.isIntersecting){entry.target.classList.add('visible')}
     else{entry.target.classList.remove('visible')}
   }),{threshold:0.08,rootMargin:'0px 0px -2% 0px'});
   $$(revealSelector).forEach((el,i)=>{el.classList.add('reveal');el.style.setProperty('--reveal-delay',`${(i%5)*55}ms`);io.observe(el)});
 }else{$$(revealSelector).forEach(el=>el.classList.add('visible'))}
 // Render the full service catalogue on the homepage, not a hand-picked subset.
 renderHomeServices();
 initServices();initDetail();initCart();initAuth();initDashboard();initAdmin();initGetHired();
 loadCustomServices();
});